const CU = [['Görüş ya da kavramın belirlenmesi (çevre)', 'sorulan görüşü ya da kavramı metindeki sözlere uygun biçimde belirler'], ['Belirlemenin metne dayandırılması (çevre)', 'belirlemesini metindeki sözlere ya da verdiği örneğe dayandırır'], ['Açık ve özgün yazım (çevre)', 'yanıtı metni kopyalamadan, anlamı bozmadan açık cümlelerle yazar']] as [[string, string], [string, string], [string, string]];
const CA = [['Durumun doğru kavranması (çevre)', 'verilen durumu ya da görüşü doğru anlayarak ele alır'], ['Görüşün ya da sorunun uygulanması (çevre)', 'istenen görüşü, soruyu ya da ilkeyi duruma uygun biçimde uygular'], ['Uygulamanın tutarlılığı (çevre)', 'uygulamayı görüşün kendi ölçütüyle çelişmeden tamamlar']] as [[string, string], [string, string], [string, string]];
const CN = [['Ögelerin ayrılması (çevre)', 'öncül, iddia, gerekçe ya da ölçüt gibi ögeleri doğru ayırır'], ['Varsayım ya da boşluğun gösterilmesi (çevre)', 'görüşün ya da argümanın dayandığı varsayımı ya da temellendirme boşluğunu gösterir'], ['Çözümlemenin gerekçelendirilmesi (çevre)', 'çözümlemesini metindeki sözlere dayanarak gerekçelendirir']] as [[string, string], [string, string], [string, string]];
const CE = [['Yargının açıkça belirtilmesi (çevre)', 'değerlendirme sorusuna açık bir yargı verir'], ['Gerekçenin görüşe dayandırılması (çevre)', 'yargısını görüşün kendi iddiasına ya da bir örneğe dayanarak gerekçelendirir'], ['Karşı noktanın hesaba katılması (çevre)', 'yargısına yöneltilebilecek bir karşı noktaya değinir']] as [[string, string], [string, string], [string, string]];
const CC = [['Özgün ürünün yazılması (çevre)', 'istenen ürünü (durum, soru, argüman, diyalog, paragraf) özgün biçimde yazar'], ['Ürünün göreve uygunluğu (çevre)', 'ürünün görevde istenen görüş, kavram ya da soruyla ilgisini gösterir'], ['Ürünün tutarlılığı (çevre)', 'ürünü kendi içinde ve metindeki görüşlerle çelişmeden kurar']] as [[string, string], [string, string], [string, string]];
const u = (s: string, k: string): Task => task('understand', s, k, ...CU);
const a = (s: string, k: string): Task => task('apply', s, k, ...CA);
const n = (s: string, k: string): Task => task('analyze', s, k, ...CN);
const e = (s: string, k: string): Task => task('evaluate', s, k, ...CE);
const c = (s: string, k: string): Task => task('create', s, k, ...CC);

